//! CLI for exercising the protocol by hand:
//!
//! ```text
//! XMPP_PASSWORD=secret XMPP_CA=certs/cert.pem xmpp-client alice@localhost [host:port]
//! ```
//!
//! - `bob@localhost hi bob` → sends a `<message type='chat'>` to bob;
//! - lines starting with `<` go raw to the server (e.g.
//!   `<iq type='get' id='1' to='localhost'><ping xmlns='urn:xmpp:ping'/></iq>`);
//! - end of input (Ctrl-D) closes the stream.
//!
//! `XMPP_CA` (optional) is an extra trusted PEM, such as the self-signed
//! certificate generated by `scripts/dev-cert.sh`.

use std::io;
use std::process::ExitCode;

use tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader};
use xmpp_client::{Client, load_ca, tls_config};
use xmpp_core::{Element, Event, Jid, STREAM_CLOSE, ns};

#[tokio::main]
async fn main() -> ExitCode {
    match run().await {
        Ok(()) => ExitCode::SUCCESS,
        Err(e) => {
            eprintln!("erro: {e}");
            ExitCode::FAILURE
        }
    }
}

async fn run() -> io::Result<()> {
    let usage = || io::Error::other("uso: XMPP_PASSWORD=... xmpp-client <jid> [host:porta]");
    let mut args = std::env::args().skip(1);
    let jid = Jid::parse(&args.next().ok_or_else(usage)?).map_err(io::Error::other)?;
    let addr = args.next();
    let password = std::env::var("XMPP_PASSWORD").map_err(|_| usage())?;
    let extra_roots = match std::env::var("XMPP_CA") {
        Ok(path) => load_ca(path.as_ref())?,
        Err(_) => Vec::new(),
    };

    let mut client =
        Client::connect(&jid, &password, addr.as_deref(), tls_config(extra_roots)?).await?;
    eprintln!("conectado como {}", client.jid);
    // Initial presence: without it the server does not consider us "available"
    // and does not deliver what is sent to our bare JID (RFC 6121 §4.2).
    client.send(&Element::new("presence", ns::CLIENT)).await?;

    // Reading in a task, writing in the main loop (see the `Client` docs).
    let Client {
        mut reader,
        mut writer,
        ..
    } = client;
    tokio::spawn(async move {
        while let Ok(Event::Element(stanza)) = reader.next().await {
            show(&stanza);
        }
        eprintln!("o servidor encerrou o stream");
        std::process::exit(0);
    });

    let mut lines = BufReader::new(tokio::io::stdin()).lines();
    while let Some(line) = lines.next_line().await? {
        let line = line.trim();
        let out = if line.starts_with('<') {
            line.to_owned()
        } else if let Some((to, body)) = line.split_once(' ') {
            Element::new("message", ns::CLIENT)
                .attr("to", to)
                .attr("type", "chat")
                .child(Element::new("body", ns::CLIENT).text(body))
                .to_string()
        } else {
            if !line.is_empty() {
                eprintln!("formato: <destinatario> <mensagem>");
            }
            continue;
        };
        writer.write_all(out.as_bytes()).await?;
        writer.flush().await?;
    }
    // End of input: polite stream shutdown (RFC 6120 §4.4).
    writer.write_all(STREAM_CLOSE.as_bytes()).await?;
    writer.flush().await
}

/// Shows messages and presences in a readable way; everything else as XML.
fn show(stanza: &Element) {
    let from = stanza.get_attr("from").unwrap_or("servidor");
    let body = stanza
        .get_child("body", ns::CLIENT)
        .map(Element::text_content);
    match (stanza.name.as_str(), body) {
        ("message", Some(body)) => println!("{from}: {body}"),
        ("presence", _) => match stanza.get_attr("type") {
            None => println!("* {from} está online"),
            Some("unavailable") => println!("* {from} ficou offline"),
            Some(kind) => println!("* {from}: presença {kind}"),
        },
        _ => println!("{stanza}"),
    }
}
